export interface Phone {
  /** The number in E.164 form, e.g. "+14155550100". */
  e164: string;
  /** The country's ISO 3166 code in lower case, e.g. "us". */
  country: string;
}

/**
 * A phone number from what a person typed, or null when it is not one. Never throws.
 * Spaces, dashes, dots and brackets in the input are ignored.
 */
export function parsePhone(input: string): Phone | null;
